  COUNT(*) FILTER (
    WHERE id = {{ $('C-V2-01 · Recevoir Demande V2').item.json.body.outil_animation_id }}
      AND categorie = 'animation'
  ) AS nb_animation_valide,
  STRING_AGG(nom || ' (' || categorie || ')', ', ') AS outils_trouves
FROM v2_outils
WHERE id IN (
  {{ $('C-V2-01 · Recevoir Demande V2').item.json.body.outil_image_id }},
  {{ $('C-V2-01 · Recevoir Demande V2').item.json.body.outil_animation_id }}
)
  AND actif = true;

