// C-V2-07 · Normaliser Scènes
// V2-010 §4 — Parsing + validation + 1 item par scène (ADR-V2-05 : N items voulu pour V2-PLAN)
// Référence dossier_id : C-V2-05 expose 'id' (pas 'dossier_id')

const dossier_id = $('C-V2-05 · Créer Dossier V2').first().json.id;

if (!dossier_id) {
  throw new Error('dossier_id introuvable — vérifier la sortie de C-V2-05 · Créer Dossier V2');
}

const results = [];

for (const item of $input.all()) {
  // Extraction du bloc texte depuis la réponse Anthropic
  // NB : Claude Sonnet 4.5 peut retourner plusieurs blocs (thinking + text)
  //      On extrait uniquement le bloc de type "text"
  let raw = '';
  if (Array.isArray(item.json.content)) {
    const textBlock = item.json.content.find(b => b.type === 'text');
    if (textBlock && textBlock.text) {
      raw = textBlock.text.trim();
    }
  }

  if (!raw) {
    throw new Error('Aucun bloc "text" trouvé dans la réponse Anthropic');
  }

  // Nettoyage défensif des balises markdown éventuelles (```json ... ```)
  if (raw.startsWith('```')) {
    raw = raw.replace(/^```[a-z]*\n?/i, '').replace(/```\s*$/, '').trim();
  }

  // Parsing JSON
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error('Échec du parsing JSON scènes : ' + raw.substring(0, 200));
  }

  // Validation structure globale
  if (!parsed.scenes || !Array.isArray(parsed.scenes)) {
    throw new Error('Structure JSON invalide : tableau scenes absent');
  }

  if (parsed.scenes.length === 0) {
    throw new Error('Tableau scenes vide — aucune scène générée');
  }

  // Validation ligne à ligne + émission d'1 item par scène
  for (const scene of parsed.scenes) {
    // Champs obligatoires présents
    if (
      scene.numero_scene === undefined ||
      scene.numero_scene === null ||
      !scene.texte_narratif ||
      String(scene.texte_narratif).trim() === '' ||
      !scene.ambiance_visuelle ||
      String(scene.ambiance_visuelle).trim() === '' ||
      scene.duree_estimee === undefined ||
      scene.duree_estimee === null
    ) {
      throw new Error(
        'Scène incomplète — champs obligatoires manquants (numero_scene, texte_narratif, ambiance_visuelle, duree_estimee) : ' +
        JSON.stringify(scene)
      );
    }

    // Validation des types
    if (typeof scene.numero_scene !== 'number' || !Number.isInteger(scene.numero_scene)) {
      throw new Error('numero_scene doit être un entier : ' + JSON.stringify(scene.numero_scene));
    }

    if (typeof scene.duree_estimee !== 'number' || scene.duree_estimee <= 0) {
      throw new Error('duree_estimee doit être un entier strictement positif : ' + JSON.stringify(scene.duree_estimee));
    }

    results.push({
      json: {
        dossier_id        : dossier_id,
        numero_scene      : scene.numero_scene,
        texte_narratif    : String(scene.texte_narratif).trim(),
        ambiance_visuelle : String(scene.ambiance_visuelle).trim(),
        duree_estimee     : Math.round(scene.duree_estimee)
      }
    });
  }
}

return results;

