// C-V2-10 · Normaliser Plans
// V2-010 §5 — Parsing + validation + N items (1 par plan)
// Correspondance item ↔ scène : préservation d'ordre par n8n (Anthropic)
// Chaque item Anthropic correspond à la scène de même index dans C-V2-08

const scenesInput = $('C-V2-08 · Persister Scènes').all();
const anthropicItems = $input.all();

if (scenesInput.length !== anthropicItems.length) {
  throw new Error(
    'Désalignement scenes/plans : ' + scenesInput.length + ' scènes mais ' +
    anthropicItems.length + ' réponses IA. Vérifier la préservation d\'ordre n8n.'
  );
}

const results = [];

for (let i = 0; i < anthropicItems.length; i++) {
  const item  = anthropicItems[i];
  const scene = scenesInput[i].json;

  // scene_id vient du RETURNING de C-V2-08 (aliasé en "scene_id")
  const scene_id     = scene.scene_id;
  const numero_scene = scene.numero_scene;
  const dossier_id   = scene.dossier_id;

  if (!scene_id) {
    throw new Error('scene_id introuvable pour l\'index ' + i + ' — vérifier C-V2-08');
  }

  // Extraction du bloc "text" de la réponse Anthropic
  let raw = '';
  if (Array.isArray(item.json.content)) {
    const textBlock = item.json.content.find(b => b.type === 'text');
    if (textBlock && textBlock.text) {
      raw = textBlock.text.trim();
    }
  }

  if (!raw) {
    throw new Error('Aucun bloc "text" trouvé pour la scène ' + numero_scene);
  }

  // Nettoyage défensif des balises markdown (TU-04)
  if (raw.startsWith('```')) {
    raw = raw.replace(/^```[a-z]*\n?/i, '').replace(/```\s*$/, '').trim();
  }

  // Parsing JSON
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(
      'Échec parsing JSON plans pour scène ' + numero_scene + ' : ' +
      raw.substring(0, 200)
    );
  }

  // Validation structure
  if (!parsed.plans || !Array.isArray(parsed.plans)) {
    throw new Error('Structure JSON invalide (scène ' + numero_scene + ') : tableau plans absent');
  }

  if (parsed.plans.length === 0) {
    throw new Error('Tableau plans vide pour la scène ' + numero_scene);
  }

  // Validation et émission d'1 item par plan
  for (const plan of parsed.plans) {
    if (
      plan.numero_plan === undefined ||
      plan.numero_plan === null ||
      !plan.description_visuelle ||
      String(plan.description_visuelle).trim() === '' ||
      plan.duree_estimee === undefined ||
      plan.duree_estimee === null
    ) {
      throw new Error(
        'Plan incomplet (scène ' + numero_scene + ') — champs obligatoires manquants : ' +
        JSON.stringify(plan)
      );
    }

    if (typeof plan.numero_plan !== 'number' || !Number.isInteger(plan.numero_plan)) {
      throw new Error('numero_plan doit être un entier (scène ' + numero_scene + ') : ' + JSON.stringify(plan.numero_plan));
    }

    if (typeof plan.duree_estimee !== 'number' || plan.duree_estimee <= 0) {
      throw new Error('duree_estimee doit être un entier positif (scène ' + numero_scene + ') : ' + JSON.stringify(plan.duree_estimee));
    }

    results.push({
      json: {
        scene_id             : scene_id,
        dossier_id           : dossier_id,
        numero_scene         : numero_scene,
        numero_plan          : plan.numero_plan,
        description_visuelle : String(plan.description_visuelle).trim(),
        duree_estimee        : Math.round(plan.duree_estimee)
      }
    });
  }
}

return results;

