SET nb_plans_total = (
  SELECT COUNT(*)
  FROM v2_plans p
  JOIN v2_scenes s ON s.id = p.scene_id
  WHERE s.dossier_id = {{ $('C-V2-05 · Créer Dossier V2').first().json.id }}
)
WHERE id = {{ $('C-V2-05 · Créer Dossier V2').first().json.id }}
RETURNING 
  id AS dossier_id, 
  nb_plans_total, 
  nb_plans_traites, 
