// C-V2-15a · Construire Prompt Image
// V2-IMG — Prépare le message utilisateur pour chaque plan
// Entrée : 18 items depuis C-V2-13 (plan + conventions outil fusionnés)
// Sortie : 18 items enrichis avec user_message prêt pour Claude

const results = [];

for (const item of $input.all()) {
  const p = item.json;

  // --- Validation des champs obligatoires ---
  if (!p.plan_id) {
    throw new Error('plan_id manquant sur un item — vérifier C-V2-13');
  }
  if (!p.description_visuelle || String(p.description_visuelle).trim() === '') {
    throw new Error('description_visuelle vide pour plan_id=' + p.plan_id);
  }
  if (!p.outil_id) {
    throw new Error('outil_id manquant pour plan_id=' + p.plan_id);
  }

  // --- Nettoyage de outil_description (retours chariot parasites) ---
  const outilDescription = String(p.outil_description || '')
    .replace(/\r\n/g, ' ')
    .replace(/\r/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const outilSpecificite = String(p.outil_specificite || '').trim();
  const outilNom         = String(p.outil_nom || '').trim();

  // --- Construction du message utilisateur ---
  const userMessage = `Outil cible : ${outilNom}
Description de l'outil : ${outilDescription}
Spécificité : ${outilSpecificite}

Scène ${p.numero_scene} — Plan ${p.numero_plan}
Durée estimée : ${p.duree_estimee} seconde(s)

Contexte narratif de la scène :
${String(p.texte_narratif).trim()}

Ambiance visuelle de la scène :
${String(p.ambiance_visuelle).trim()}

Description visuelle du plan :
${String(p.description_visuelle).trim()}

Génère un prompt image optimisé pour ${outilNom}, prêt à être copié-collé directement dans l'interface.`;

  // --- Propagation des champs nécessaires aux nœuds suivants ---
  results.push({
    json: {
      plan_id       : p.plan_id,
      scene_id      : p.scene_id,
      dossier_id    : p.dossier_id,
      outil_id      : p.outil_id,
      execution_id  : p.execution_id,
      numero_scene  : p.numero_scene,
      numero_plan   : p.numero_plan,
      duree_estimee : p.duree_estimee,
      user_message  : userMessage
    }
  });
}

return results;

// C-V2-15c · Normaliser Prompts
// V2-IMG — Parse les réponses Claude et prépare les données pour UPSERT
// Entrée : 18 items depuis C-V2-15b (réponses Anthropic)
// Corrélation par index : item[i] de C-V2-15b ↔ item[i] de C-V2-15a
// Sortie : 18 items avec plan_id, outil_id, texte_prompt, parametres_recommandes

const contextItems  = $('C-V2-15a · Construire Prompt Image').all();
const anthropicItems = $input.all();

if (contextItems.length !== anthropicItems.length) {
  throw new Error(
    'Désalignement contexte/LLM : ' + contextItems.length + ' contextes mais ' +
    anthropicItems.length + ' réponses IA. Vérifier la préservation d\'ordre n8n.'
  );
}

const results = [];

for (let i = 0; i < anthropicItems.length; i++) {
  const item    = anthropicItems[i];
  const context = contextItems[i].json;

  const plan_id      = context.plan_id;
  const outil_id     = context.outil_id;
  const numero_scene = context.numero_scene;
  const numero_plan  = context.numero_plan;

  if (!plan_id) {
    throw new Error('plan_id introuvable pour index ' + i + ' — vérifier C-V2-15a');
  }

  let raw = '';
  if (Array.isArray(item.json.content)) {
    const textBlock = item.json.content.find(b => b.type === 'text');
    if (textBlock && textBlock.text) {
      raw = textBlock.text.trim();
    }
  }

  if (!raw) {
    throw new Error(
      'Aucun bloc "text" trouvé pour plan_id=' + plan_id +
      ' (scène ' + numero_scene + ', plan ' + numero_plan + ')'
    );
  }

  if (raw.startsWith('```')) {
    raw = raw.replace(/^```[a-z]*\n?/i, '').replace(/```\s*$/, '').trim();
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(
      'Échec parsing JSON pour plan_id=' + plan_id + ' : ' +
      raw.substring(0, 200)
    );
  }

  if (
    !parsed.texte_prompt ||
    String(parsed.texte_prompt).trim() === ''
  ) {
    throw new Error('texte_prompt vide pour plan_id=' + plan_id);
  }

  const parametresRecommandes = parsed.parametres_recommandes
    ? String(parsed.parametres_recommandes).trim()
    : '';

  results.push({
    json: {
      plan_id                : plan_id,
      outil_id               : outil_id,
      numero_scene           : numero_scene,
      numero_plan            : numero_plan,
      texte_prompt           : String(parsed.texte_prompt).trim(),
      parametres_recommandes : parametresRecommandes
    }
  });
}

return results;
